import {
  Component,
  signal,
  OnInit,
  inject,
  ViewChild,
  ElementRef,
  OnDestroy,
} from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { EmployeesService } from '../../../services/employees.service';
import {
  DepartmentService,
  Department,
} from '../../../services/department.service';
import { Employee } from '../../../models/employee.model';
import { TranslationService } from '../../../services/translation.service';
import { LangService } from '../../../services/lang.service';
import { RolesService } from '../../../services/roles.service';
import { Role } from '../../../models/role.model';

@Component({
  selector: 'app-add-employee',
  standalone: false,
  templateUrl: './add-employee.html',
  styleUrl: './add-employee.css',
})
export class AddEmployee implements OnInit, OnDestroy {
  private formBuilder = inject(FormBuilder);
  private router = inject(Router);
  private employeesService = inject(EmployeesService);
  private departmentsService = inject(DepartmentService);
  private translationService = inject(TranslationService);
  private langService = inject(LangService);
  private rolesService = inject(RolesService);

  // Form
  employeeForm!: FormGroup;

  // Data
  departments = signal<Array<{ id: number; nameAr: string; nameEn: string }>>(
    []
  );
  roles = signal<Role[]>([]);

  // UI State
  submitted = signal(false);
  submitting = signal(false);
  showSuccessDialog = signal(false);
  successMessage = signal('');
  showErrorDialog = signal(false);
  errorMessage = signal('');
  showPassword = signal(false);

  // Language
  currentLang = signal<'ar' | 'en'>('en');
  isRTL = signal(false);

  private errorTimeoutId: ReturnType<typeof setTimeout> | null = null;

  ngOnInit() {
    this.initializeForm();
    this.loadDepartments();
    this.loadRoles();
    this.initializeLanguage();
  }

  ngOnDestroy(): void {
    this.hideErrorMessage();
  }

  private initializeLanguage() {
    this.langService.currentLang$.subscribe((lang) => {
      this.currentLang.set(lang);
      this.isRTL.set(lang === 'ar');
    });
  }

  private initializeForm() {
    this.employeeForm = this.formBuilder.group({
      firstName: ['', [Validators.required, Validators.minLength(2)]],
      lastName: ['', [Validators.required, Validators.minLength(2)]],
      email: ['', [Validators.required, Validators.email]],
      password: [
        '',
        [
          Validators.required,
          Validators.minLength(8),
          this.passwordStrengthValidator(),
        ],
      ],
      jobTitle: ['', [Validators.required]],
      role: ['', [Validators.required]],
      phoneNumber: ['', [Validators.pattern(/^[+]?[\d\s\-\(\)]{5,}$/)]],
      nationalId: [''],
      hireDate: [''],
      departmentId: [''],
      timeZone: ['Asia/Dubai'],
    });
  }

  private passwordStrengthValidator() {
    return (control: any) => {
      const password = control.value;
      if (!password) return null;

      const hasUpperCase = /[A-Z]/.test(password);
      const hasLowerCase = /[a-z]/.test(password);
      const hasNumbers = /\d/.test(password);
      const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password);

      if (hasUpperCase && hasLowerCase && hasNumbers && hasSpecialChar) {
        return null;
      }

      return { passwordStrength: true };
    };
  }

  private loadDepartments() {
    this.departmentsService.getDepartmentNames().subscribe({
      next: (departments) => {
        this.departments.set(departments);
      },
      error: (error: any) => {
        console.error('Error loading departments:', error);
      },
    });
  }

  private loadRoles(): void {
    this.rolesService.getRoles().subscribe({
      next: (response) => {
        if (response.success && response.data && response.data.items) {
          this.roles.set(response.data.items);
        }
      },
      error: (error) => {
        console.error('Error loading roles:', error);
      },
    });
  }

  isFieldInvalid(fieldName: string): boolean {
    const field = this.employeeForm.get(fieldName);
    return !!(
      field &&
      field.invalid &&
      (field.dirty || field.touched || this.submitted())
    );
  }

  getErrorMessage(fieldName: string): string {
    const field = this.employeeForm.get(fieldName);
    if (field && field.errors) {
      if (field.errors['required']) {
        return this.translate('common.field_required');
      }
      if (field.errors['email']) {
        return this.translate('login.email_invalid');
      }
      if (field.errors['minlength']) {
        const requiredLength = field.errors['minlength'].requiredLength;
        return this.translate('common.min_length').replace(
          '%min%',
          requiredLength.toString()
        );
      }
      if (field.errors['passwordStrength']) {
        return this.translate('reset_password.password_strength_error');
      }
      if (field.errors['pattern']) {
        if (fieldName === 'phoneNumber') {
          return this.translate('users.phone_invalid_format');
        }
        if (fieldName === 'nationalId') {
          return this.translate('common.field_required');
        }
      }
    }
    return '';
  }

  private showSuccessMessage(message: string) {
    this.hideErrorMessage();
    this.successMessage.set(message);
    this.showSuccessDialog.set(true);

    // Auto-hide after 3 seconds
    setTimeout(() => {
      this.showSuccessDialog.set(false);
      this.successMessage.set('');
    }, 3000);
  }

  onSubmit() {
    this.submitted.set(true);

    if (this.employeeForm.invalid) {
      return;
    }

    this.submitting.set(true);

    // Clean and prepare employee data
    const formValue = this.employeeForm.value;
    const employeeData: any = {
      email: formValue.email,
      password: formValue.password,
      firstName: formValue.firstName,
      lastName: formValue.lastName,
      jobTitle: formValue.jobTitle,
      role: formValue.role,
      timeZone: formValue.timeZone || 'Asia/Dubai',
    };

    // Add optional fields only if they have values
    if (formValue.departmentId) {
      employeeData.departmentId = parseInt(formValue.departmentId);
    }

    if (formValue.phoneNumber && formValue.phoneNumber.trim()) {
      employeeData.phoneNumber = formValue.phoneNumber.trim();
    }

    if (formValue.nationalId && formValue.nationalId.trim()) {
      employeeData.nationalId = formValue.nationalId.trim();
    }

    if (formValue.hireDate && formValue.hireDate.trim()) {
      employeeData.hireDate = formValue.hireDate;
    }

    this.employeesService.addEmployee(employeeData).subscribe({
      next: (response) => {
        this.submitting.set(false);
        this.showSuccessMessage(
          this.translate('employees.employee_created_successfully')
        );

        // Reset form
        this.employeeForm.reset();
        this.submitted.set(false);

        // Navigate back to employees list after a short delay
        setTimeout(() => {
          this.router.navigate(['/employees']);
        }, 2000);
      },
      error: (error) => {
        console.error('Error creating employee:', error);
        this.submitting.set(false);
        const backendMessage = error?.error?.message;
        let message = this.translate('employees.employee_create_failed');
        if (backendMessage) {
          const lowerMsg = backendMessage.toLowerCase();
          if (
            lowerMsg.includes('email') &&
            lowerMsg.includes('exists')
          ) {
            message = this.translate('employees.employee_email_exists');
          } else {
            message = backendMessage;
          }
        } else if (error?.message) {
          message = error.message;
        }
        this.showErrorMessage(message);
      },
    });
  }

  goBack() {
    this.router.navigate(['/employees']);
  }

  togglePasswordVisibility() {
    this.showPassword.set(!this.showPassword());
  }

  private showErrorMessage(message: string) {
    this.hideErrorMessage();
    this.errorMessage.set(message);
    this.showErrorDialog.set(true);
    this.errorTimeoutId = setTimeout(() => {
      this.hideErrorMessage();
    }, 5000);
  }

  private hideErrorMessage() {
    if (this.errorTimeoutId) {
      clearTimeout(this.errorTimeoutId);
      this.errorTimeoutId = null;
    }
    this.showErrorDialog.set(false);
    this.errorMessage.set('');
  }

  // Translation helper
  translate(key: string): string {
    return this.translationService.translate(key);
  }

  getRoleDisplayName(role: Role): string {
    const currentLang = this.currentLang();
    if (currentLang === 'ar' && role.arabicName) {
      return role.arabicName;
    }
    return role.name;
  }
}
